    __m128i t1 = _mm_clmulepi64_si128(hi, r, 0x00);
    __m128i t2 = _mm_clmulepi64_si128(hi, r, 0x11);
    return _mm_xor_si128(_mm_xor_si128(lo, t1), t2);
}

static inline __m128i ghash_mult(__m128i x, __m128i h)
